def ttl_cache(maxsize=128, ttl=600, timer=time.monotonic, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Least Recently Used (LRU)
    algorithm with a per-item time-to-live (TTL) value.
    """

    class CacheEntry:
        def __init__(self, value, timestamp):
            self.value = value
            self.timestamp = timestamp

    class TTLCache:
        def __init__(self, maxsize, ttl, timer, typed):
            self.maxsize = maxsize
            self.ttl = ttl
            self.timer = timer
            self.typed = typed
            self.cache = OrderedDict()

        def __getitem__(self, key):
            if key not in self.cache:
                raise KeyError(key)
            entry = self.cache[key]
            if self.timer() - entry.timestamp > self.ttl:
                del self.cache[key]
                raise KeyError(key)
            return entry.value

        def __setitem__(self, key, value):
            if self.typed and not isinstance(key, type(value)):
                raise TypeError("Key and value must be of the same type")
            if key in self.cache:
                del self.cache[key]
            self.cache[key] = CacheEntry(value, self.timer())

        def __delitem__(self, key):
            if key not in self.cache:
                raise KeyError(key)
            del self.cache[key]

        def __contains__(self, key):
            if key not in self.cache:
                return False
            entry = self.cache[key]
            if self.timer() - entry.timestamp > self.ttl:
                del self.cache[key]
                return False
            return True

        def __len__(self):
            return len(self.cache)

        def __iter__(self):
            return iter(self.cache)

        def __repr__(self):
            return repr(self.cache)

    def wrapper(func):
        cache = TTLCache(maxsize, ttl, timer, typed)
        def wrapped(*args, **kwargs):
            key = (args, frozenset(kwargs.items())) if typed else (args, kwargs)
            try:
                return cache[key]
            except KeyError:
                result = func(*args, **kwargs)
                cache[key] = result
                return result
        return wrapped

    return wrapper
