def lfu_cache(maxsize=128, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Least Frequently Used (LFU)
    algorithm.

    """

    class LFUCache:
        def __init__(self, maxsize, typed):
            self.maxsize = maxsize
            self.typed = typed
            self.cache = {}
            self.access_count = {}
            self.size = 0

        def __getitem__(self, key):
            if key not in self.cache:
                raise KeyError(key)
            self.access_count[key] += 1
            return self.cache[key]

        def __setitem__(self, key, value):
            if self.size >= self.maxsize:
                self._evict()
            self.cache[key] = value
            self.access_count[key] = 1
            self.size += 1

        def __delitem__(self, key):
            if key not in self.cache:
                raise KeyError(key)
            del self.cache[key]
            del self.access_count[key]
            self.size -= 1

        def __contains__(self, key):
            return key in self.cache

        def __len__(self):
            return self.size

        def _evict(self):
            min_count = min(self.access_count.values())
            for key in list(self.access_count.keys()):
                if self.access_count[key] == min_count:
                    del self.cache[key]
                    del self.access_count[key]
                    break

    def decorator(func):
        cache = LFUCache(maxsize, typed)
        def wrapper(*args, **kwargs):
            key = (args, frozenset(kwargs.items())) if typed else (args, kwargs)
            if key in cache:
                return cache[key]
            result = func(*args, **kwargs)
            cache[key] = result
            return result
        return wrapper

    return decorator
