@classmethod
def extostr(cls, e, max_level=30, max_path_level=5):
    """
    Format an exception.
    :param e: Any exception instance.
    :type e: Exception
    :param max_level: Maximum call stack level (default 30)
    :type max_level: int
    :param max_path_level: Maximum path level (default 5)
    :type max_path_level: int
    :return The exception readable string
    :rtype str
    """
    stack = []
    while e and len(stack) < max_level:
        stack.append(e)
        e = e.__cause__ or e.__context__

    if not stack:
        return str(e)

    result = []
    for i, exc in enumerate(stack):
        result.append(f"  {i}: {exc}")

        if max_path_level > 0:
            path = []
            while exc and len(path) < max_path_level:
                path.append(exc.__class__.__name__)
                exc = exc.__cause__ or exc.__context__

            if path:
                result.append(f"    Path: {' -> '.join(path)}")

    return "\n".join(result)
