def validate_fixity(self, fixity, manifest_files):
    """Validate fixity block in inventory.

    Check the structure of the fixity block and makes sure that only files
    listed in the manifest are referenced.
    """
    if not isinstance(fixity, dict):
        raise ValueError("Fixity block must be a dictionary")

    if 'files' not in fixity:
        raise ValueError("Fixity block must contain a 'files' key")

    files = fixity['files']

    if not isinstance(files, list):
        raise ValueError("Files list must be a list")

    for file in files:
        if not isinstance(file, dict):
            raise ValueError("Each file entry must be a dictionary")

        if 'path' not in file:
            raise ValueError("Each file entry must contain a 'path' key")

        if 'algorithm' not in file:
            raise ValueError("Each file entry must contain an 'algorithm' key")

        if 'checksum' not in file:
            raise ValueError("Each file entry must contain a 'checksum' key")

        path = file['path']
        algorithm = file['algorithm']
        checksum = file['checksum']

        if path not in manifest_files:
            raise ValueError(f"File '{path}' is not listed in the manifest")

        if algorithm not in ['md5', 'sha1', 'sha256']:
            raise ValueError(f"Unsupported algorithm '{algorithm}'")

        if checksum != self.calculate_checksum(path, algorithm):
            raise ValueError(f"Checksum mismatch for file '{path}'")

    return True
```

