def validate_min_max_args(self, args):
    """Check if value of arguments is between minimum and maximum values.

    :param args: The received arguments.
    """
    for key, value in args.items():
        if hasattr(self, key):
            min_value = getattr(self, key + '_min')
            max_value = getattr(self, key + '_max')
            if min_value is not None and value < min_value:
                raise ValueError(f"Value of {key} is less than the minimum allowed value of {min_value}.")
            if max_value is not None and value > max_value:
                raise ValueError(f"Value of {key} is greater than the maximum allowed value of {max_value}.")
