def get_plugin_spec_flatten_dict(plugin_dir):
    """Creates a flat dict from the plugin spec

    :param plugin_dir: A path to the plugin's dir
    :return: A flatten dictionary contains the plugin's properties
    """
    import os
    import json

    # Initialize an empty dictionary to store the flattened plugin spec
    plugin_spec = {}

    # Walk through the plugin directory
    for root, dirs, files in os.walk(plugin_dir):
        for file in files:
            if file.endswith('.json'):
                # Construct the full file path
                file_path = os.path.join(root, file)

                # Open and load the JSON file
                with open(file_path, 'r', encoding='utf-8') as f:
                    spec = json.load(f)

                # Flatten the JSON spec
                def flatten_dict(d, parent_key='', sep='.'):
                    items = []
                    for k, v in d.items():
                        new_key = f"{parent_key}{sep}{k}" if parent_key else k
                        if isinstance(v, dict):
                            items.extend(flatten_dict(v, new_key, sep=sep).items())
                        else:
                            items.append((new_key, v))
                    return dict(items)

                # Update the plugin_spec dictionary with the flattened spec
                plugin_spec.update(flatten_dict(spec))

    return plugin_spec
```

